// Entire CLI plugin for OpenCode
// Auto-generated by `entire enable --agent opencode`
// Do not edit manually — changes will be overwritten on next install.
//
// TEMPORARY DIAGNOSTIC BUILD: captures raw v2 event shapes for porting.
// Uses node:child_process so hooks work under both Bun (OpenCode CLI/TUI)
// and Node (OpenCode Desktop's Electron sidecar).
import { spawn, spawnSync } from "node:child_process"
import { appendFileSync } from "node:fs"

const DEBUG_LOG = "/private/var/folders/nl/kk62_qbs24b0v3fcv2_502s40000gn/T/opencode/entire-plugin-events.jsonl"

function dbg(label: string, data: unknown) {
  try {
    appendFileSync(DEBUG_LOG, JSON.stringify({ t: new Date().toISOString(), label, data }) + "\n")
  } catch {
    // ignore
  }
}

export default {
  id: "entire",
  async setup(ctx: any) {
    dbg("setup", { directory: ctx.location?.directory, version: ctx.app?.version })

    try {
      const controller = new AbortController()
      ;(async () => {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          dbg("event", event)
        }
      })().catch((e) => dbg("subscribe_error", String(e)))
      return () => controller.abort()
    } catch (e) {
      dbg("setup_error", String(e))
    }
  },
}

