```ts
import { spawn, spawnSync } from "node:child_process"

export default {
  id: "entire",
  async setup(ctx) {
    const seenSessions = new Set<string>()
    let currentSessionID: string | null = null
    let currentModel: string | null = null
    let pendingInjection: string | null = null

    function hookCmd(hookName) { ... same ... }

    function callHook(hookName, payload) { ... spawn async ... }
    function callHookSync(hookName, payload) { ... spawnSync ... }

    function parseInjectedContext(stdout) { ... same ... }

    function fireTurnStart(sessionID, model) {
      const json = JSON.stringify({ session_id: sessionID, prompt: "", model: model ?? "" })
      const [cmd, ...args] = hookCmd("turn-start")
      const proc = spawnSync(cmd, args, { cwd: ctx.location.directory, input: json + "\n", encoding: "utf8", stdio: ["pipe","pipe","ignore"] })
      const out = proc.stdout
      const injected = parseInjectedContext(typeof out === "string" ? out : "")
      if (injected) pendingInjection = injected
    }

    function ensureSessionStart(sessionID) {
      if (!sessionID || seenSessions.has(sessionID)) return
      seenSessions.add(sessionID)
      currentSessionID = sessionID
      callHook("session-start", { session_id: sessionID })
    }

    // Register the context (system prompt) hook once for injections
    try {
      await ctx.session.hook("context", (event) => {
        if (!pendingInjection) return
        if (event.sessionID && currentSessionID && event.sessionID !== currentSessionID) return
        event.system.push({ type: "text", text: pendingInjection })
        pendingInjection = null
      })
    } catch (e) { /* don't crash */ }

    const controller = new AbortController()
    ;(async () => {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        try {
          const data = event?.data
          switch (event?.type) {
            case "session.step.started": {
              const sessionID = data?.sessionID
              if (!sessionID) break
              ensureSessionStart(sessionID)
              currentSessionID = sessionID
              if (data?.model) currentModel = data.model.id ?? null
              fireTurnStart(sessionID, currentModel)
              break
            }
            case "session.step.ended": {
              if (data?.sessionID) {
                callHook("turn-end", { session_id: data.sessionID, model: currentModel ?? "" })
              }
              break
            }
            case "session.compacted": {
              callHook("compaction", { session_id: data?.sessionID ?? currentSessionID })
              break
            }
            case "session.compaction.ended": {
              // v2 alternative name for safety
              break
            }
            case "session.deleted": {
              const sessionID = data?.info?.id ?? data?.sessionID ?? currentSessionID
              if (sessionID) {
                callHookSync("session-end", { session_id: sessionID })
                seenSessions.delete(sessionID)
                currentSessionID = null
                pendingInjection = null
              }
              break
            }
            case "session.usage.updated": {
              // ensure session-start even if step events were missed
              const sessionID = data?.sessionID
              if (sessionID) {
                ensureSessionStart(sessionID)
                if (!currentSessionID) currentSessionID = sessionID
              }
              break
            }
          }
        } catch { /* ignore */ }
      }
    })().catch(() => {})

    return () => {
      controller.abort()
      if (currentSessionID) {
        callHookSync("session-end", { session_id: currentSessionID })
      }
    }
  },
}
```

