// Entire CLI plugin for OpenCode
// Auto-generated by `entire enable --agent opencode`
// NOTE: adapted for OpenCode v2 plugin API (default export with id + setup).
// Original v1-format plugin did not load under OpenCode v2.
//
// Uses node:child_process so hooks work under both Bun (OpenCode CLI/TUI)
// and Node (OpenCode Desktop's Electron sidecar). See #2014.
import { spawn, spawnSync } from "node:child_process"

export default {
  id: "entire",
  async setup(ctx: any) {
    // In-memory per-plugin state (mirrors the v1 plugin's tracking)
    const seenSessions = new Set<string>()
    // Track current session ID for events that only carry a sessionID
    let currentSessionID: string | null = null
    // Track the model used by the most recent assistant step
    let currentModel: string | null = null
    // One-time model-context injection captured from turn-start's stdout,
    // applied on the next LLM call via the session "context" hook.
    let pendingInjection: string | null = null

    const directory: string = ctx.location?.directory ?? process.cwd()

    /**
     * Build the shell command for a hook invocation.
     * Uses sh -c so the command is guarded by a `command -v` probe: when the
     * entire binary is not on PATH the hook exits 0 rather than failing the
     * surrounding OpenCode operation.
     */
    function hookCmd(hookName: string): string[] {
      return ["sh", "-c", `if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks opencode ${hookName}`]
    }

    /**
     * Pipe JSON payload to an entire hooks command (async).
     * Errors are logged but never thrown — plugin failures must not crash OpenCode.
     */
    async function callHook(hookName: string, payload: Record<string, unknown>) {
      try {
        const json = JSON.stringify(payload)
        const [cmd, ...args] = hookCmd(hookName)
        await new Promise<void>((resolve) => {
          const proc = spawn(cmd, args, {
            cwd: directory,
            stdio: ["pipe", "ignore", "ignore"],
          })
          proc.on("error", () => resolve())
          proc.on("close", () => resolve())
          proc.stdin?.end(json + "\n")
        })
      } catch {
        // Silently ignore — plugin failures must not crash OpenCode
      }
    }

    /**
     * Synchronous variant used where the session state must be ready before
     * subsequent work (e.g. a fast mid-turn commit hitting git hooks) or
     * before process exit.
     */
    function callHookSync(hookName: string, payload: Record<string, unknown>) {
      try {
        const json = JSON.stringify(payload)
        const [cmd, ...args] = hookCmd(hookName)
        spawnSync(cmd, args, {
          cwd: directory,
          input: json + "\n",
          stdio: ["pipe", "ignore", "ignore"],
        })
      } catch {
        // Silently ignore — plugin failures must not crash OpenCode
      }
    }

    /**
     * parseInjectedContext scans a hook's stdout for Entire's injection envelope
     * ({"inject_context":"..."}) and returns the text to inject, or null.
     */
    function parseInjectedContext(stdout: string | Buffer): string | null {
      const text = typeof stdout === "string" ? stdout : String(stdout ?? "")
      for (const line of text.split("\n")) {
        const trimmed = line.trim()
        if (!trimmed.startsWith("{")) continue
        try {
          const parsed = JSON.parse(trimmed) as { inject_context?: unknown }
          if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
            return parsed.inject_context
          }
        } catch {
          // not our envelope — ignore
        }
      }
      return null
    }

    /**
     * fireTurnStart starts a turn synchronously (session state must be ready
     * before mid-turn commits) and stashes any model-context injection emitted
     * on stdout for the session "context" hook to apply. Entire emits the
     * injection at most once per session, so pendingInjection is set only when
     * turn-start actually returns it.
     */
    function fireTurnStart(sessionID: string, model: string | null) {
      try {
        const json = JSON.stringify({
          session_id: sessionID,
          prompt: "",
          model: model ?? "",
        })
        const [cmd, ...args] = hookCmd("turn-start")
        const proc = spawnSync(cmd, args, {
          cwd: directory,
          input: json + "\n",
          encoding: "utf8",
          stdio: ["pipe", "pipe", "ignore"],
        })
        const out = proc.status === 0 ? proc.stdout : null
        const injected = parseInjectedContext(out)
        if (injected) pendingInjection = injected
      } catch {
        // Silently ignore — plugin failures must not crash OpenCode
      }
    }

    /**
     * ensureSessionStart registers the session with Entire exactly once per
     * session, guaranteeing session-start precedes the first turn-start.
     */
    function ensureSessionStart(sessionID: string) {
      if (!sessionID || seenSessions.has(sessionID)) return
      seenSessions.add(sessionID)
      currentSessionID = sessionID
      callHook("session-start", { session_id: sessionID })
    }

    // Apply the one-time Entire context injection captured at turn-start by
    // appending it to the system instructions for the next LLM call.
    try {
      await ctx.session.hook("context", (event: any) => {
        if (!pendingInjection) return
        if (event.sessionID && currentSessionID && event.sessionID !== currentSessionID) return
        if (Array.isArray(event.system)) {
          event.system.push({ type: "text", text: pendingInjection })
          pendingInjection = null
        }
      })
    } catch {
      // Hook API unavailable — context injection is best-effort only.
    }

    const controller = new AbortController()
    ;(async () => {
      try {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          try {
            const data = event?.data ?? {}
            switch (event?.type) {
              case "session.step.started": {
                // Start of an assistant step (token of a user turn under v2's
                // step-based event model). Mirrors v1's per-message turn-start.
                const sessionID = data?.sessionID as string | undefined
                if (!sessionID) break
                ensureSessionStart(sessionID)
                currentSessionID = sessionID
                if (data?.model?.id) currentModel = data.model.id
                fireTurnStart(sessionID, currentModel)
                break
              }

              case "session.step.ended": {
                // End of an assistant step — end the corresponding turn so
                // Entire's session metadata stays current. The next
                // step.started re-activates the session for linking.
                const sessionID = data?.sessionID as string | undefined
                if (sessionID) {
                  callHook("turn-end", { session_id: sessionID, model: currentModel ?? "" })
                }
                break
              }

              case "session.compacted": {
                const sessionID = (data?.sessionID as string | undefined) ?? currentSessionID
                if (sessionID) {
                  callHook("compaction", { session_id: sessionID })
                }
                break
              }

              case "session.deleted": {
                const sessionID = (data?.sessionID as string | undefined) ?? currentSessionID
                if (sessionID) {
                  callHookSync("session-end", { session_id: sessionID })
                  seenSessions.delete(sessionID)
                  currentSessionID = null
                  pendingInjection = null
                }
                break
              }

              case "session.usage.updated": {
                // Safety net: register the session even if step events were
                // missed (e.g. plugin hot-reloaded mid-session).
                const sessionID = data?.sessionID as string | undefined
                if (sessionID) {
                  ensureSessionStart(sessionID)
                  if (!currentSessionID) currentSessionID = sessionID
                }
                break
              }
            }
          } catch {
            // Per-event guard — plugin failures must not crash OpenCode
          }
        }
      } catch {
        // Subscription ended or failed — ignore.
      }
    })()

    // Cleanup on plugin unload (OpenCode shutdown / reload).
    return () => {
      controller.abort()
      if (currentSessionID) {
        callHookSync("session-end", { session_id: currentSessionID })
      }
    }
  },
}

